// === Tab: mySketch ===
var particles = [];
var img = [];
var n, s, maxR;
var indexImg = 0;
var isTransitioning = false;

// 定义动画阶段的常量
const SETTLE_FRAME_COUNT = 300; 
const FADE_DURATION = 1;
const AUTO_SWITCH_FRAME = 250; 

function preload() {
	img.push(loadImage('https://openprocessing.org/sketch/2690894/files/Las amapolas - Claude Monet.png'));
	img.push(loadImage('https://openprocessing.org/sketch/2690894/files/Autorretrato - Vicent Van Gogh.png'));
	img.push(loadImage('https://openprocessing.org/sketch/2690894/files/La lechera de burdeos - Francisco de Goya.jpg'));
	img.push(loadImage('https://openprocessing.org/sketch/2690894/files/Muchacho mirando una aparicion - Francisco de Goya.png'));
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	background("#FFEDDA");
	smooth();

	n = 10000; 
	s = 2; 
	maxR = height/2 - height/20;

	createNewParticles();
}

function draw() {
    // --- 新增功能 ---
    // 在第 250 帧时，自动触发一次切换
    if (frameCount === AUTO_SWITCH_FRAME) {
        triggerTransition();
    }

	if (frameCount > 30) {
		background(255, 237, 218, 2); 
	}

	translate(width/2, height/2);
	noStroke();

	for (let i = particles.length - 1; i >= 0; i--) {
		let p = particles[i];
		p.move();
		p.update();
		p.show();

		if (p.isDead()) {
			particles.splice(i, 1);
		}
	}
}

function createNewParticles() {
    noiseSeed(millis()); 
    frameCount = 0;

    for (let i = 0; i < n; i++) {
        var p = new Particle(maxR, s);
        let x = int(map(p.pos.x, -maxR, maxR, 0, img[indexImg].width));
        let y = int(map(p.pos.y, -maxR, maxR, 0, img[indexImg].height));
        p.c = img[indexImg].get(x, y);
        particles.push(p);
    }
}

// --- 修改点 1：将切换逻辑提取到新函数中 ---
function triggerTransition() {
    if (isTransitioning) {
        return; 
    }
    isTransitioning = true;

    for (let p of particles) {
        p.beginFadeOut();
    }

    // 让图片可以循环切换
    indexImg = 0;

    createNewParticles();

    isTransitioning = false;
}

// --- 修改点 2：mousePressed 现在只调用新函数 ---
function mousePressed() {
    triggerTransition();
}

class Particle {
  constructor(maxR_, s_) {
    this.s = s_;
    this.c = color(0);
    this.maxR = maxR_; 

    this.state = 'fading_in';
    this.alpha = 0;
    this.fadeStep = 255 / FADE_DURATION;
    
    this.init();
  }
  
  init() {
    this.pos = p5.Vector.random2D();
    this.pos.normalize();
    this.pos.mult(random(2, this.maxR));
    this.vel = createVector();
  }

  update() {
    if (this.state === 'fading_in') {
        this.alpha += this.fadeStep;
        if (this.alpha >= 255) {
            this.alpha = 255;
            this.state = 'active';
        }
    } else if (this.state === 'fading_out') {
        this.alpha -= this.fadeStep;
    }
  }

  beginFadeOut() {
    this.state = 'fading_out';
  }

  isDead() {
    return this.state === 'fading_out' && this.alpha <= 0;
  }

  show() {
    let cWithAlpha = color(this.c);
    cWithAlpha.setAlpha(this.alpha);
    fill(cWithAlpha);
    ellipse(this.pos.x, this.pos.y, this.s, this.s);
  }
  
  move() {
    if (this.state === 'active' && frameCount < SETTLE_FRAME_COUNT) {
        var angle = noise(this.pos.x / 400, this.pos.y / 600, frameCount / 150) * TAU;
        this.vel.set(cos(angle), sin(angle));
        this.vel.mult(0.2); 
    } else {
        this.vel.mult(0.97); 
    }
    this.pos.add(this.vel);

    if (this.state !== 'fading_out') {
        let d = this.pos.mag();
        if (d > this.maxR) {
            this.pos.setMag(this.maxR);
            this.vel.mult(0);
        }
    }
  }
}

